// Controlled RLS v3 gRPC wire adapter over real TLS/H2; no external Go modules.
package main
import("bytes";"encoding/binary";"encoding/json";"fmt";"io";"net";"net/http";"os";"strings";"time")
func field(n int,v []byte)[]byte{out:=binary.AppendUvarint(nil,uint64(n<<3|2));out=binary.AppendUvarint(out,uint64(len(v)));return append(out,v...)}
func integer(n int,v uint64)[]byte{return binary.AppendUvarint(binary.AppendUvarint(nil,uint64(n<<3)),v)}
func parse(data []byte)(map[int][][]byte,error){
 out:=map[int][][]byte{}
 for len(data)>0{
  key,n:=binary.Uvarint(data);if n<=0{return nil,fmt.Errorf("bad key")};data=data[n:];number:=int(key>>3)
  switch key&7{
  case 0:_,n=binary.Uvarint(data);if n<=0{return nil,fmt.Errorf("bad integer")};data=data[n:]
  case 1:if len(data)<8{return nil,io.ErrUnexpectedEOF};data=data[8:]
  case 2:size,m:=binary.Uvarint(data);if m<=0||size>uint64(len(data)-m){return nil,io.ErrUnexpectedEOF};data=data[m:];out[number]=append(out[number],append([]byte(nil),data[:int(size)]...));data=data[int(size):]
  case 5:if len(data)<4{return nil,io.ErrUnexpectedEOF};data=data[4:]
  default:return nil,fmt.Errorf("unsupported wire")}
 };return out,nil
}
func first(fields map[int][][]byte,n int)[]byte{if len(fields[n])==0{return nil};return fields[n][0]}
func frameRead(r io.Reader)([]byte,error){head:=make([]byte,5);if _,e:=io.ReadFull(r,head);e!=nil{return nil,e};n:=binary.BigEndian.Uint32(head[1:]);if head[0]!=0||n>32768{return nil,fmt.Errorf("bounded uncompressed request required")};body:=make([]byte,n);_,e:=io.ReadFull(r,body);return body,e}
func frameWrite(w io.Writer,body []byte){head:=make([]byte,5);binary.BigEndian.PutUint32(head[1:],uint32(len(body)));w.Write(head);w.Write(body)}
func main(){
 if len(os.Args)!=4{panic("certificate,key,private counter URL required")}
