  reject:=func(){w.WriteHeader(200);w.Header().Set("Grpc-Status","13")}
  if r.ProtoMajor!=2||r.Method!="POST"||r.URL.Path!="/envoy.service.ratelimit.v3.RateLimitService/ShouldRateLimit"||!strings.HasPrefix(r.Header.Get("Content-Type"),"application/grpc"){reject();return}
